export function registerComponentPrototype(proto) {
  if (!proto) return;
  if (!window.localTangoComponentPrototypes) {
    window.localTangoComponentPrototypes = {};
  }
  if (proto.name) {
    window.localTangoComponentPrototypes[proto.name] = proto;
  }
}
